echo '--- 脚本语法 ---'; bash -n /tmp/wifi_survey.sh && echo '语法 OK'; echo; echo '--- 解析器对模拟数据输出 ---'; python3 - <<'PYEOF'
import re
nets = []
cur = None
with open('/tmp/scan_raw.txt') as f:
    for line in f:
        s = line.strip()
        if s.startswith('BSS '):
            if cur: nets.append(cur)
            cur = {'bssid': s.split()[1], 'freq': None, 'signal': None, 'ssid': None,
                   'km': [], 'pmf': 'none'}
        elif cur is None:
            continue
        elif s.startswith('freq:'):
            cur['freq'] = s.split(':')[1].strip()
        elif s.startswith('signal:'):
            cur['signal'] = s.split(':')[1].split()[0]
        elif s.startswith('SSID:'):
            cur['ssid'] = s.split(':', 1)[1].strip()
        elif s.startswith('*') and ('SAE' in s or 'PSK' in s or 'OWE' in s):
            cur['km'].append(s)
        elif s.startswith('*') and ('PMF' in s or 'MFP' in s):
            cur['pmf'] = s
if cur: nets.append(cur)

def classify(n):
    km = ' '.join(n['km'])
    has_sae, has_psk = 'SAE' in km, 'PSK' in km
    if has_sae and has_psk: return 'WPA2/WPA3 混合', '可测(WPA2侧)'
    if has_sae:              return 'WPA3-SAE',    '不可离线破'
    if has_psk:              return 'WPA2-PSK',    '可测'
    return '开放', '无加密'

print(f"{'SSID':<18} {'信道':<5} {'信号':<9} {'加密':<13} {'PMF':<4} {'可测性':<10}")
print('-'*70)
for n in sorted(nets, key=lambda x: (x['ssid'] or '', x['bssid'])):
    if not n['ssid']:
        print('(隐藏SSID被跳过)'); continue
    f = int(n['freq']) if n['freq'] else 0
    ch = int((f-2407)/5) if 0 < f < 5000 else (int((f-5000)/5) if f else '?')
    sec, t = classify(n)
    pmf = '需' if 'required' in n['pmf'] else ('支' if 'capable' in n['pmf'] else '-')
    print(f"{n['ssid'][:18]:<18} {ch:<5} {n['signal'] or '?':<9} {sec:<13} {pmf:<4} {t:<10}")
PYEOF
